});

import frappe
from frappe.tests.utils import FrappeTestCase

from helpdesk.api.permission import has_app_permission
from helpdesk.test_utils import create_agent


class TestPermission(FrappeTestCase):
    website_user = "helpdesk-website-user@example.com"
    manager_user = "helpdesk-manager@example.com"
    original_user = None

    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        cls.original_user = frappe.session.user

    def tearDown(self):
        frappe.set_user(self.original_user or "Administrator")

    def test_agent_can_access_helpdesk_app(self):
        create_agent("helpdesk-agent@example.com")

        frappe.set_user("helpdesk-agent@example.com")

        self.assertTrue(has_app_permission())

    def test_agent_manager_can_access_helpdesk_app(self):
        user = self._get_or_create_user(self.manager_user)
        user.add_roles("Agent Manager")

        frappe.set_user(self.manager_user)

        self.assertTrue(has_app_permission())

    def test_regular_website_user_cannot_access_helpdesk_app(self):
        self._get_or_create_user(self.website_user)

        frappe.set_user(self.website_user)

        self.assertFalse(has_app_permission())

    def _get_or_create_user(self, email):
        if frappe.db.exists("User", email):
            return frappe.get_doc("User", email)

        return frappe.get_doc(
            {
                "doctype": "User",
                "email": email,
                "first_name": email.split("@")[0],
                "send_welcome_email": 0,
            }
        ).insert(ignore_permissions=True)

import frappe

ALLOWED_APP_ROLES = {
    "Agent",
    "Agent Manager",
    "System Manager",
    "HD Customer",
    "HD Customer Manager",
}


def has_app_permission():
    """Check if the user has permission to access the app."""
    if frappe.session.user == "Administrator":
        return True

    return bool(ALLOWED_APP_ROLES.intersection(frappe.get_roles()))

import type { Page } from "@playwright/test";
import { expect, test, uid, usePersona } from "../helpers/fixtures";
import { raiseTicket } from "../helpers/factories";
import { PASSWORD, personas } from "../helpers/personas";
import { expectDenied, type Api } from "../helpers/api";
import { loginContext, openTicketInList } from "../helpers/portal";

test.describe("plain agent", () => {
  usePersona("agent");

  test("cannot delete tickets, create agents or see admin settings", async ({
    page,
    api,
    apiAs,
    ticket,
  }) => {
    const agent = await apiAs("agent");

    await expectDenied(agent.raw("frappe.client.delete", { doctype: "HD Ticket", name: ticket.name }));
    await expectDenied(
      agent.raw("frappe.client.insert", {
        doc: { doctype: "HD Agent", user: personas.agent2.email, agent_name: "Nope" },
      })
    );

    await page.goto(`/helpdesk/tickets/${ticket.name}`);
    await page.locator("#app-header").getByRole("button").filter({ hasNotText: /\S/ }).last().click();
    await expect(page.getByRole("menuitem", { name: "Merge Ticket" })).toBeVisible();
    await expect(page.getByRole("menuitem", { name: "Delete" })).toHaveCount(0);
    await page.keyboard.press("Escape");

    await selectRow(page, api, personas.agent.email, ticket.name);
    await openSelectionMenu(page);
    await expect(page.getByRole("menuitem", { name: "Edit" })).toBeVisible();
    await expect(page.getByRole("menuitem", { name: "Delete" })).toHaveCount(0);
    await page.keyboard.press("Escape");

    await openSettings(page);
    const settings = page.getByRole("dialog");
    await expect(settings.getByText("Preferences")).toBeVisible();
    for (const tab of ["Email Accounts", "General", "Agents", "SLA Policies"]) {
      await expect(settings.getByText(tab, { exact: true })).toHaveCount(0);
    }
  });
});

